/* CSS Reset */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    /* Root Variables */
    :root {
      --primary-blue: #1e5f8f;
      --secondary-gold: #d4af37;
      --text-dark: #2c3e50;
      --text-light: #ffffff;
      --bg-light: #f8f9fa;
      --bg-white: #ffffff;
      --border-color: #dee2e6;
      --shadow: 0 2px 8px rgba(0,0,0,0.1);
      --transition: all 0.3s ease;
    }

    /* Typography */
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      color: var(--text-dark);
      background-color: var(--bg-light);
    }

    h1, h2, h3 {
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 1rem;
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 2rem; }
    h3 { font-size: 1.5rem; }

    /* Header */
    header {
      background-color: var(--primary-blue);
      color: var(--text-light);
      padding: 1rem 0;
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: var(--shadow);
    }

    .header-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .logo {
      font-size: 1.5rem;
      font-weight: 700;
    }

    .language-toggle {
      padding: 0.5rem 1rem;
      border: 2px solid var(--text-light);
      border-radius: 4px;
      background: transparent;
      color: var(--text-light);
      cursor: pointer;
      font-weight: 600;
      transition: var(--transition);
    }

    .language-toggle:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .language-toggle:focus {
      outline: 2px solid var(--secondary-gold);
      outline-offset: 2px;
    }

    [data-lang="es"] .lang-es,
    [data-lang="en"] .lang-en {
      display: none;
    }

    /* Main Layout */
    .bilingual-container {
      max-width: 1400px;
      margin: 0 auto;
      transition: var(--transition);
    }

    /* Desktop: Side-by-side */
    @media (min-width: 768px) {
      .bilingual-container {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 2rem;
        padding: 2rem 1rem;
      }

      .bilingual-container[data-lang="es"] .content-en {
        opacity: 0.3;
      }

      .bilingual-container[data-lang="en"] .content-es {
        opacity: 0.3;
      }
    }

    /* Mobile: Stacked with toggle */
    @media (max-width: 767px) {
      .bilingual-container {
        display: block;
        padding: 1rem;
      }

      .bilingual-container[data-lang="es"] .content-en {
        display: none;
      }

      .bilingual-container[data-lang="en"] .content-es {
        display: none;
      }
    }

    .content-es,
    .content-en {
      transition: opacity 0.3s ease;
    }

    /* Sections */
    section {
      background: var(--bg-white);
      padding: 2rem;
      margin-bottom: 2rem;
      border-radius: 8px;
      box-shadow: var(--shadow);
    }

    /* Hero Section */
    .hero {
      background: linear-gradient(135deg, var(--primary-blue) 0%, #2c7fb8 100%);
      color: var(--text-light);
      text-align: center;
      padding: 3rem 2rem;
    }

    .hero h1 {
      margin-bottom: 0.5rem;
    }

    .hero-tagline {
      font-size: 1.25rem;
      margin-bottom: 2rem;
      opacity: 0.9;
    }

    .cta-buttons {
      display: flex;
      gap: 1rem;
      justify-content: center;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-block;
      padding: 0.75rem 1.5rem;
      border-radius: 4px;
      text-decoration: none;
      font-weight: 600;
      transition: var(--transition);
    }

    .btn-primary {
      background: var(--secondary-gold);
      color: var(--text-dark);
    }

    .btn-primary:hover {
      background: #c49c2e;
      transform: translateY(-2px);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text-light);
      border: 2px solid var(--text-light);
    }

    .btn-secondary:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    /* Stats */
    .stats {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 1.5rem;
      margin-top: 2rem;
    }

    .stat {
      text-align: center;
    }

    .stat-number {
      font-size: 2rem;
      font-weight: 700;
      color: var(--primary-blue);
    }

    .stat-label {
      font-size: 0.9rem;
      color: #6c757d;
    }

    /* Menu Sections */
    .menu-section {
      margin-bottom: 2rem;
    }

    .menu-header {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 1.5rem;
      padding-bottom: 0.75rem;
      border-bottom: 2px solid var(--border-color);
    }

    .menu-icon {
      font-size: 2rem;
    }

    .menu-items {
      display: grid;
      gap: 1.5rem;
    }

    .menu-item {
      padding: 1rem;
      border-left: 3px solid var(--primary-blue);
      background: var(--bg-light);
      border-radius: 0 4px 4px 0;
    }

    .menu-item.specialty {
      border-left-color: var(--secondary-gold);
      background: #fffbf0;
    }

    .menu-item-header {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.5rem;
    }

    .menu-item-name {
      font-weight: 600;
      font-size: 1.1rem;
      color: var(--text-dark);
    }

    .menu-item-price {
      font-weight: 700;
      color: var(--primary-blue);
      font-size: 1.1rem;
    }

    .menu-item-description {
      font-size: 0.95rem;
      color: #6c757d;
      line-height: 1.5;
    }

    .specialty-badge {
      display: inline-block;
      padding: 0.25rem 0.5rem;
      background: var(--secondary-gold);
      color: var(--text-dark);
      border-radius: 3px;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      margin-left: 0.5rem;
    }

    /* Contact Section */
    .contact-info {
      display: grid;
      gap: 1rem;
    }

    .contact-item {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    .contact-icon {
      font-size: 1.5rem;
      color: var(--primary-blue);
    }

    .contact-details {
      flex: 1;
    }

    .contact-label {
      font-weight: 600;
      margin-bottom: 0.25rem;
    }

    /* Footer */
    footer {
      background-color: var(--text-dark);
      color: var(--text-light);
      padding: 2rem 1rem;
      text-align: center;
    }

    .footer-content {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-note {
      font-size: 0.9rem;
      opacity: 0.8;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
    }

    /* Accessibility */
    .skip-link {
      position: absolute;
      top: -40px;
      left: 0;
      background: var(--primary-blue);
      color: var(--text-light);
      padding: 0.5rem 1rem;
      text-decoration: none;
      z-index: 100;
    }

    .skip-link:focus {
      top: 0;
    }

    /* Utilities */
    .text-center { text-align: center; }
    .mb-1 { margin-bottom: 1rem; }
    .mb-2 { margin-bottom: 2rem; }

// Language toggle functionality
    (function() {
      const container = document.querySelector('.bilingual-container');
      const toggle = document.querySelector('.language-toggle');
      const htmlElement = document.documentElement;

      // Get initial language from URL hash or default to Spanish
      const getInitialLang = () => {
        const hash = window.location.hash;
        if (hash === '#lang=en') return 'en';
        if (hash === '#lang=es') return 'es';
        return 'es'; // default
      };

      let currentLang = getInitialLang();
      container.setAttribute('data-lang', currentLang);
      htmlElement.setAttribute('lang', currentLang);
      htmlElement.setAttribute('data-lang', currentLang);

      // Toggle function
      toggle.addEventListener('click', () => {
        currentLang = currentLang === 'es' ? 'en' : 'es';
        container.setAttribute('data-lang', currentLang);
        htmlElement.setAttribute('lang', currentLang);
        htmlElement.setAttribute('data-lang', currentLang);
        window.location.hash = `lang=${currentLang}`;
      });

      // Handle back/forward browser navigation
      window.addEventListener('hashchange', () => {
        currentLang = getInitialLang();
        container.setAttribute('data-lang', currentLang);
        htmlElement.setAttribute('lang', currentLang);
        htmlElement.setAttribute('data-lang', currentLang);
      });
    })();

    // WebMCP Tool Definitions
    window.mcpTools = {
      'toggle-language': {
        name: 'toggle-language',
        description: 'Switch between Spanish and English language versions',
        inputSchema: {
          type: 'object',
          properties: {
            lang: {
              type: 'string',
              enum: ['es', 'en'],
              description: 'Target language code'
            }
          },
          required: ['lang']
        },
        execute: async (params) => {
          const { lang } = params;
          const container = document.querySelector('.bilingual-container');
          const htmlElement = document.documentElement;
          container.setAttribute('data-lang', lang);
          htmlElement.setAttribute('lang', lang);
          htmlElement.setAttribute('data-lang', lang);
          window.location.hash = `lang=${lang}`;
          return { success: true, currentLang: lang };
        }
      },
      'menu-query': {
        name: 'menu-query',
        description: 'Query menu items by category or search term',
        inputSchema: {
          type: 'object',
          properties: {
            category: {
              type: 'string',
              enum: ['beverages', 'appetizers', 'fish', 'meat', 'desserts'],
              description: 'Menu category to query'
            },
            search: {
              type: 'string',
              description: 'Search term for menu items'
            }
          }
        },
        execute: async (params) => {
          // Extract menu data from DOM
          const menuItems = Array.from(document.querySelectorAll('.menu-item')).map(item => ({
            name: item.querySelector('.menu-item-name').textContent,
            price: item.querySelector('.menu-item-price').textContent,
            description: item.querySelector('.menu-item-description').textContent,
            specialty: item.classList.contains('specialty')
          }));
          return { success: true, items: menuItems };
        }
      },
      'reservation-info': {
        name: 'reservation-info',
        description: 'Get restaurant contact and reservation information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            info: {
              phone: '+34 952 XXX XXX',
              email: 'info@losgranainos.es',
              hours: '12:00-16:00 and 19:00-23:30 (Daily)',
              address: 'Cala de Mijas, Costa del Sol, Málaga, Spain',
              coordinates: { lat: 36.5167, lng: -4.6333 }
            }
          };
        }
      },
      'location-info': {
        name: 'location-info',
        description: 'Get geographic location and directions information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            location: {
              address: 'Cala de Mijas, Costa del Sol, Málaga, Spain',
              coordinates: { lat: 36.5167, lng: -4.6333 },
              region: 'Andalusia',
              nearbyLandmarks: ['Cala de Mijas Beach', 'Costa del Sol', 'Málaga City']
            }
          };
        }
      }
    };

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });
